        .{ .path = "root.newKittyImages", .constructs = gostty.KittyImages },
        .{ .path = "root.freeKittyImages", .destroys = gostty.KittyImages },
        .{ .path = "Terminal.setKittyGraphicsSizeLimit" },
        .{
