            .covers = &.{"Terminal.setKittyGraphicsLoadingLimits"},
        },
        .{ .path = "root.kittyImage" },
        .{ .path = "root.kittyImageData", .params = &.{ any, out } },

        // System hooks: process-global, answered from inside the callback the
