        .{ .path = "root.sys.onPngDecodeRequest" },
        .{ .path = "root.sys.replyPngImage", .params = &.{ any, any, bytes } },
        .{ .path = "root.sys.onSecureRandomRequest" },
        .{ .path = "root.sys.clear" },
        .{ .path = "root.sys.replySecureRandom", .params = &.{bytes} },

